sp_widget.client_script:
api.controller = function($scope, $element) {
  var c = this;

  c.scrollLeft = function() {
    var track = document.getElementById('gpUpcomingTrack');
    if (!track) return;
    track.scrollBy({ left: -track.clientWidth, behavior: 'smooth' });
  };

  c.scrollRight = function() {
    var track = document.getElementById('gpUpcomingTrack');
    if (!track) return;
    track.scrollBy({ left: track.clientWidth, behavior: 'smooth' });
  };
};

sp_widget.css:
/* ─── Reset ───────────────────────────────────────────── */
.gp-section *,
.gp-section *::before,
.gp-section *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* ─── Section ─────────────────────────────────────────── */
.gp-section {
  font-family: 'Inter', 'Plus Jakarta Sans', 'Segoe UI', sans-serif;
  background: linear-gradient(114deg, rgb(84, 60, 168) 17%, rgb(88, 107, 199) 114%);
  width: calc(100% + 30px);
  margin-left: -15px;
  margin-right: -15px;
  padding: 64px 0 72px;
}

/* ─── Inner container ─────────────────────────────────── */
.gp-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 60px;
}

/* ─── Header ──────────────────────────────────────────── */
.gp-header {
  margin-bottom: 40px;
}

.gp-title {
  font-size: 24px;
  font-weight: 600;
  color: #ffffff;
  line-height: 1.2;
  margin-bottom: 12px;
  letter-spacing: -0.01em;
}

.gp-subtitle {
  font-size: 14px;
  font-weight: 400;
  color: rgba(255, 255, 255, 0.72);
  line-height: 1.65;
}

/* ─── 2-column grid ───────────────────────────────────── */
.gp-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
}

/* ─── Card ────────────────────────────────────────────── */
.gp-card {
  background: rgba(255, 255, 255, 0.10);
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 16px;
  padding: 28px 28px 24px;
  display: flex;
  flex-direction: column;
  transition: background 0.2s ease, transform 0.2s ease;
  backdrop-filter: blur(6px);
}

.gp-card:hover {
  background: rgba(255, 255, 255, 0.15);
  transform: translateY(-2px);
}

/* ─── Badge ───────────────────────────────────────────── */
.gp-card-badge {
  display: inline-flex;
  align-items: center;
  background: rgba(255, 255, 255, 0.15);
  border: 1px solid rgba(255, 255, 255, 0.22);
  color: rgba(255, 255, 255, 0.85);
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  padding: 4px 10px;
  border-radius: 100px;
  margin-bottom: 14px;
  width: fit-content;
}

/* ─── Title ───────────────────────────────────────────── */
.gp-card-title {
  font-size: 16px;
  font-weight: 700;
  color: #ffffff;
  line-height: 1.35;
  margin-bottom: 10px;
}

/* ─── Description ─────────────────────────────────────── */
.gp-card-desc {
  font-size: 13px;
  font-weight: 400;
  color: rgba(255, 255, 255, 0.70);
  line-height: 1.6;
  margin-bottom: 18px;
}

/* ─── Meta ────────────────────────────────────────────── */
.gp-card-meta {
  display: flex;
  flex-direction: column;
  gap: 7px;
  margin-bottom: 22px;
}

.gp-card-meta-row {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  color: rgba(255, 255, 255, 0.80);
}

.gp-meta-icon {
  width: 14px;
  height: 14px;
  color: rgba(255, 255, 255, 0.70);
  flex-shrink: 0;
}

.gp-meta-sep {
  color: rgba(255, 255, 255, 0.40);
  font-size: 11px;
}

/* ─── Button ──────────────────────────────────────────── */
.gp-card-btn {
  display: block;
  width: 100%;
  padding: 11px 20px;
  background: rgba(255, 255, 255, 0.14);
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 10px;
  color: rgba(255, 255, 255, 0.90);
  font-size: 13px;
  font-weight: 500;
  text-align: center;
  text-decoration: none !important;
  cursor: pointer;
  transition: background 0.2s ease, color 0.2s ease;
  margin-top: auto;
  letter-spacing: 0.01em;
}

.gp-card-btn:hover {
  background: rgba(255, 255, 255, 0.24);
  color: #ffffff;
}

/* ─── Empty state ─────────────────────────────────────── */
.gp-empty {
  text-align: center;
  color: rgba(255, 255, 255, 0.60);
  font-size: 14px;
  padding: 40px 0;
}

/* ─── Responsive ──────────────────────────────────────── */
@media (max-width: 1024px) {
  .gp-inner { padding: 0 40px; }
}

@media (max-width: 768px) {
  .gp-section { padding: 48px 0 56px; }
  .gp-inner   { padding: 0 24px; }
  .gp-grid    { grid-template-columns: 1fr; }
  .gp-title   { font-size: 22px; }
}

@media (max-width: 480px) {
  .gp-inner { padding: 0 16px; }
  .gp-card  { padding: 22px 20px 20px; }
}

sp_widget.script:
(function() {
  data.programs = [];

  var gr = new GlideRecordSecure('x_enno_gatenow_grant_program');
  gr.addQuery('active', true);
  gr.addQuery('status', 'Published');
  gr.orderBy('proposal_open_date');
  gr.query();

  while (gr.next()) {
    var rec = {};
    rec.sys_id              = gr.getUniqueValue();
    rec.program_name        = gr.getDisplayValue('program_name');
    rec.program_category    = gr.getDisplayValue('category');
    rec.program_description = gr.getDisplayValue('description');
    rec.proposal_open_date  = gr.getDisplayValue('proposal_open_date');
    rec.program_budget      = gr.getDisplayValue('program_budget');
    data.programs.push(rec);
  }
})();
